// ***************
// Filename: uart_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of uart: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to uart's logic on named ports, its status
//   comes back on input ports. UART control, baud rate (fractional), status
//   and error count. Generated by ip/scripts/regmap_gen.py from
//   uart_regs.json: edit the JSON and regenerate (the IP_VERSION / IP_DATE
//   stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "UART" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        RW   line settings, reset 0x3
//                       [0] TX_EN: transmitter on
//                       [1] RX_EN: receiver on
//                       [2] PAR_EN: parity on
//                       [3] PAR_ODD: odd parity
//                       [4] STOP2: two stop bits
//                       [5] LOOPBACK: internal loopback
//                       [7:6] BITS: data bits: 0 = 8, 1 = 7, 2 = 6, 3 = 5
//     0x14 FCW         RW   baud generator frequency control word (16 x baud
//                       / clock x 2^32), reset FCW_RST
//     0x18 STATUS      CMD  state and sticky errors (write 1 to clear the
//                       errors)
//                       [0] TX_BUSY: transmitting
//                       [1] RX_BUSY: receiving
//                       [2] RX_AVAIL: received data available
//                       [8] FRAME_ERR: framing error (W1C)
//                       [9] PARITY_ERR: parity error (W1C)
//                       [10] OVERRUN: receive FIFO overrun (W1C)
//                       [30:16] RX_LEVEL: receive FIFO level
//     0x1C ERR_CNT     RO   frames received with an error
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-16
module uart_regs #(
  parameter logic [31:0] FCW_RST = 32'd0  // FCW at reset (the BAUD parameter)
) (
  input  logic          aclk,           // clock
  input  logic          aresetn,        // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: uart_regs_if.regs (src/include/uart_regs_if.sv) {ctrl_o=cfg_ctrl ctrl_wr_o=cfg_ctrl_wr fcw_o=cfg_fcw fcw_wr_o=cfg_fcw_wr status_i=sts_status status_o=cfg_status status_wr_o=cfg_status_wr err_cnt_i=sts_err_cnt}
  uart_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [32-1:0] ctrl_o;
  logic ctrl_wr_o;
  logic [32-1:0] fcw_o;
  logic fcw_wr_o;
  logic [32-1:0] status_i;
  logic [32-1:0] status_o;
  logic status_wr_o;
  logic [32-1:0] err_cnt_i;
  assign r.cfg_ctrl = ctrl_o;
  assign r.cfg_ctrl_wr = ctrl_wr_o;
  assign r.cfg_fcw = fcw_o;
  assign r.cfg_fcw_wr = fcw_wr_o;
  assign status_i = r.sts_status;
  assign r.cfg_status = status_o;
  assign r.cfg_status_wr = status_wr_o;
  assign err_cnt_i = r.sts_err_cnt;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "UART";
  localparam logic [31:0] IP_VERSION = "1.00";
  localparam logic [31:0] IP_DATE    = 32'h10112026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_FCW = 8'h14;
  localparam logic [7:0] A_STATUS = 8'h18;
  localparam logic [7:0] A_ERR_CNT = 8'h1C;
  localparam int MAP_WORDS = 8;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] fcw_q;
  logic [31:0] status_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= 32'h3;
      ctrl_wr_o <= 1'b0;
      fcw_q <= 32'(FCW_RST);
      fcw_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_ERR_CNT);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        fcw_wr_o <= wr_en && wa == A_FCW;
        if (wr_en && wa == A_FCW) fcw_q <= (fcw_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[32-1:0];
  assign fcw_o = fcw_q[32-1:0];
  assign status_o = status_q[32-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = ctrl_q;
      A_FCW: rd_data = fcw_q;
      A_STATUS: rd_data = 32'(status_i);
      A_ERR_CNT: rd_data = 32'(err_cnt_i);
      default: begin
      end
    endcase
  end
endmodule
